import * as React from 'react';
import Card from '@mui/material/Card';
import CardContent from '@mui/material/CardContent';
import CardMedia from '@mui/material/CardMedia';
import Typography from '@mui/material/Typography';
import { Button, CardActionArea, CardActions } from '@mui/material';

export default function DefaultCard() {
  return (
    <Card sx={{ maxWidth: "100%", height: "350px" }}>
      <CardActionArea>
        <CardMedia
          component="img"
          height="40"
          image="/static/images/eye01.png"
          alt="green iguana"
        />
        <CardContent>
          <Typography gutterBottom variant="h5" component="div">
          Cataracts
          </Typography>
          <Typography variant="body2" color="text.secondary">
          Delve into the world of cataracts, a common eye condition that clouds the lens, affecting vision clarity. Understand the causes, symptoms, and types of cataracts, and explore various treatment options such as lifestyle changes, prescription lenses, and advanced surgical procedures. Learn how early detection and proper management can restore clear vision and improve the quality of life for those affected by this eye disease.          </Typography>
        </CardContent>
      </CardActionArea>
    </Card>
  );
}
